import json,hashlib,sys,platform,importlib,csv,math,re
from solve import ROOT
from check import check_fleet
def audit():
    cfg=json.loads((ROOT/'configs/base.json').read_text());paper=(ROOT/'paper/paper.md').read_text();rows=[]
    def gate(req,source,observation,passed,limit='',violations=None):rows.append({'requirement_id':req,'source_id':source,'observation':observation,'status':'pass' if passed else 'fail','violating_items':violations or [],'tolerance':1e-7,'limit':limit,'checker':'author self-check; not independent acceptance'})
    for name in ['fixed_T1','fixed_T2','mixed_count','mixed_cost']:
      d=json.loads((ROOT/f'results/final/{name}.json').read_text());r=check_fleet(d['fleet'],cfg,True);s=d['statistics'];expected_volume=sum(math.prod(c['dims'])*c['quantity'] for c in cfg['cargo']);expected_mass=sum(c['weight']*c['quantity'] for c in cfg['cargo']);gate(name,'P1b/P2a/P2b/A1',{'counts':r['counts'],'statistics':s},r['valid'] and s['volume_cm3']==expected_volume and s['weight_kg']==expected_mass,'static full-support local-pressure interpretation; optimum not established',r['errors'])
    single=json.loads((ROOT/'results/final/single_pareto.json').read_text())['solutions'];gate('Q1_SINGLE','P1a/P1c',{'candidate_counts':{v:len(ps) for v,ps in single.items()},'epsilon_scan':str((ROOT/'results/final/epsilon_scan.json').relative_to(ROOT))},all(check_fleet(p['fleet'],cfg,False)['valid'] for ps in single.values() for p in ps),'searched finite Pareto set, not global front')
    frozen=json.loads((ROOT/'configs/experiments.json').read_text())['scenarios'];exps=json.loads((ROOT/'results/sensitivity/experiments.json').read_text());gate('Q3_PARAMETERS','P3',{'declared':len(frozen),'completed':sum(r.get('status')=='checked' for r in exps)},len(exps)==len(frozen) and all(r.get('status')=='checked' and r['feasible'] for r in exps),'one-instance deterministic scenarios; no statistical generalization')
    bt=json.loads((ROOT/'review/boundary_tests.json').read_text());gate('BOUNDARY_REJECTION','A1g/A1f/A1o/A1p/A1h',{'tests':len(bt)},all(r['test_pass'] for r in bt),'finite targeted defects, not exhaustive proof of checker reliability')
    rr=json.loads((ROOT/'review/repair_regression.json').read_text());gate('F1_INFORMED_REGRESSION','disclosed F1 + adjacent controls',{'passed':rr['passed'],'total':rr['total']},rr['passed']==rr['total'],'informed author self-check, not blind acceptance')
    ar=json.loads((ROOT/'review/affected_layout_recheck.json').read_text());gate('AFFECTED_LAYOUTS','all published layouts',{'passed':ar['passed'],'total':ar['total_fleets']},ar['passed']==ar['total_fleets'],'static recheck, not new optimization')
    smoke=json.loads((ROOT/'results/smoke_v3.json').read_text());sr=check_fleet(smoke['fleet'],smoke['config'],True);gate('SMOKE_V3','A1/P4',{'count':sr['counts'],'vehicles':len(smoke['fleet']),'lower_bound':1},sr['valid'] and len(smoke['fleet'])==1,'old v1 smoke failed stricter directional check and is retained; only v3 accepted')
    repro=json.loads((ROOT/'results/clean_reproduction_final/reproduction_report.json').read_text());gate('REPRODUCE','P4',repro,all(r['feasible'] and r['metrics_match'] and r['geometry_match'] for r in repro['comparisons']),'author clean output; same host')
    qa=json.loads((ROOT/'paper/qa/render_report.json').read_text());gate('PAPER','U1/P3/P4',{'chars':len(paper),'pdf_pages':qa['pages'],'sections':len(re.findall(r'^## ',paper,re.M)),'tables_figures':True},len(paper)>10000 and all(x in paper for x in ['问题1','问题2','问题3','参考资料','限制']) and not qa['out_of_page_text_blocks'] and qa.get('visual_review_completed',False),'self-defined practice format; no official submission/rule verification')
    rows+= [{'requirement_id':'GLOBAL_OPTIMALITY','source_id':'P1b/P2','status':'unverified','observation':'feasible N1=20,N2=10,mixed=10,C=7000; global necessary lower bounds N1=16,N2/mixed=7,C=4900','violating_items':[],'tolerance':None,'limit':'99-pattern master proved only restricted-pool optimality','checker':'author'}, {'requirement_id':'INDEPENDENT_ACCEPTANCE','source_id':'handoff','status':'unverified','observation':'initial independent review completed: 5 pass, a4 fail F1; informed repair is not independent re-review; re-review pending','violating_items':[],'tolerance':None,'limit':'producer self-check cannot establish independence','checker':'unavailable in this execution'}, {'requirement_id':'A2_BUSINESS_GENERALITY','source_id':'P5/A2','status':'unverified','observation':'64 real geometry pairs audited; mass, quantity, category, payload, trip-cost basis missing','violating_items':[],'tolerance':None,'limit':'optional business validation not executable from supplied fields','checker':'author'}]
    (ROOT/'review/check_report.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2),encoding='utf8')
    versions={'python':sys.version,'platform':platform.platform(),'cpu_logical_count':__import__('os').cpu_count(),'libraries':{n:importlib.import_module(n).__version__ for n in ['numpy','scipy','matplotlib','pandas','docx','openpyxl','reportlab','pypdf']}}
    (ROOT/'logs/environment.json').write_text(json.dumps(versions,ensure_ascii=False,indent=2),encoding='utf8')
    manifest={str(p.relative_to(ROOT)):hashlib.sha256(p.read_bytes()).hexdigest() for d in ['src','configs','results/final','figures','paper'] for p in (ROOT/d).rglob('*') if p.is_file() and '/qa/' not in str(p).replace('\\','/')};(ROOT/'logs/artifact_manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2),encoding='utf8')
    if any(r['status']=='fail' for r in rows):raise RuntimeError([r for r in rows if r['status']=='fail'])
    print('Delivery self-check mandatory checks passed; global optimality/independence/A2 business remain unverified.')
if __name__=='__main__':audit()
